package com.bank.wal.service;
import com.bank.wal.model.ChangeEvent;
import java.util.*;
import java.util.logging.*;
import java.util.stream.*;

public class WalShipper {
    private static final Logger log = Logger.getLogger(WalShipper.class.getName());
    static {
        Handler h = new ConsoleHandler(); h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false); log.addHandler(h);
    }
    // PHYSICAL: replay raw byte-level records for EVERY table, exact copy
    public List<String> physicalReplicate(List<String> walBytes) {
        List<String> standby = new ArrayList<>(walBytes);   // byte-for-byte
        log.info(() -> "PHYSICAL replicated " + standby.size() + " WAL records (all tables, exact copy)");
        return standby;
    }
    // LOGICAL: decode to row-change events, keep only the published table(s)
    public List<ChangeEvent> logicalReplicate(List<ChangeEvent> decoded, Set<String> publishedTables) {
        List<ChangeEvent> out = decoded.stream()
            .filter(e -> publishedTables.contains(e.getTable()))
            .collect(Collectors.toList());
        log.info(() -> "LOGICAL published " + out.size() + " row events for " + publishedTables);
        return out;
    }
}
