package com.bank.wal;
import com.bank.wal.model.ChangeEvent;
import com.bank.wal.service.WalShipper;
import java.util.*;
import java.util.logging.*;

public class WalDemo {
    public static void main(String[] args) {
        WalShipper shipper = new WalShipper();
        // Physical: raw WAL for all tables
        shipper.physicalReplicate(List.of("0x01 accounts", "0x02 audit_internal", "0x03 accounts"));
        // Logical: decoded events, publish only accounts
        List<ChangeEvent> decoded = List.of(
            new ChangeEvent("accounts","UPDATE","{id:SAV2001,balance:950000}"),
            new ChangeEvent("audit_internal","INSERT","{note:internal}"),
            new ChangeEvent("accounts","INSERT","{id:CUR3001,balance:250000}"));
        shipper.logicalReplicate(decoded, Set.of("accounts"))
               .forEach(e -> System.out.println("to-kafka -> " + e));
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n", r.getMillis(), r.getLevel(), formatMessage(r));
    }
}
